#include "KS/SRC/stringx.h"

typedef float time_value_t;

enum anim_flags_t {
    ANIM_REVERSE = 0x0001,
    ANIM_LOOPING = 0x0002,
    ANIM_AUTOKILL = 0x0004,
    ANIM_ATTACHED = 0x0010
};

class anim_control_t {
public:
    float current_time;
    float time_delta;
    float duration;
    float timescale_factor;
    float cntrl_tween_duration;
    float tween_timer;
    unsigned int flags;
    short loop_count;

    inline float get_time() const { return current_time; }
    inline bool is_flagged(anim_flags_t flag) const { return flags & flag; }
};

template <class animatable_t>
class anim {
protected:
    unsigned short flags;

public:
    virtual inline void set_flag(anim_flags_t flag) { flags |= flag; }
    virtual inline void clear_flag(anim_flags_t flag) { flags &= ~flag; }
    virtual inline void set_flag(anim_flags_t flag, bool enabled) {
        if (enabled) set_flag(flag); else clear_flag(flag);
    }
    virtual inline void set_time(float time) {}
    virtual inline void frame_advance(const anim_control_t &, animatable_t *) {}
    virtual inline void get_value(const anim_control_t &, animatable_t *) const {}
    virtual inline void get_value(float, animatable_t *) const {}
    inline bool is_flagged(anim_flags_t flag) const { return flags & flag; }
};

class entity;
class entity_track_tree;
class entity_widget;

class entity_anim_tree : public anim<entity *> {
    char data_before_name[0x34];
    stringx name;
    char data_before_control[4];
    anim_control_t control;

public:
    inline bool is_attached() const {
        return is_flagged(ANIM_ATTACHED);
    }
    inline const stringx &get_name() const {
        return name;
    }
    inline bool is_finished() const {
        if (control.is_flagged(ANIM_AUTOKILL)) {
            if (control.loop_count == -1 || control.loop_count > 0)
                return false;
        }
        if (control.is_flagged(ANIM_REVERSE))
            return control.current_time <= 0.0f;
        return control.current_time >= control.duration;
    }
    inline unsigned short get_flags() const {
        return flags;
    }
    inline float get_time() const {
        return control.get_time();
    }
    void reset_root_position();
};

class entity_widget {
public:
    void kill_anim(entity_anim_tree *);
};

class world_dynamics_system {
public:
    void kill_anim(entity_anim_tree *);
};

class anim_maker {
public:
    entity_anim_tree *create_anim(
        const stringx &, const entity_track_tree &, const entity_track_tree &,
        float, float, entity *, unsigned short, float, int, short, entity_widget *);
    void create_anim(
        entity_anim_tree *, const stringx &, const entity_track_tree &,
        const entity_track_tree &, float, float, unsigned short, float, int,
        short, entity_widget *);
};

class entity {
    char data_before_anim_trees[0xe8];
    entity_anim_tree *anim_trees[10];
    char data_before_owning_widget[4];
    entity_widget *owning_widget;

public:
    void make_animateable(bool);
    entity_anim_tree *play_anim(
        int, const stringx &, const entity_track_tree &,
        const entity_track_tree &, float, float, float, unsigned short, short);
};

extern world_dynamics_system *g_world_ptr;
extern anim_maker *g_anim_maker;

__asm__(".equ g_world_ptr, 0x00431A8C");
__asm__(".equ g_anim_maker, 0x004318CC");
__asm__(".equ make_animateable__6entityb, 0x00134590");
__asm__(".equ kill_anim__13entity_widgetP16entity_anim_tree, 0x002B9BD8");
__asm__(".equ kill_anim__21world_dynamics_systemP16entity_anim_tree, 0x002A3710");
__asm__(".equ create_anim__10anim_makerP16entity_anim_treeRC7stringxRC17entity_track_treeUsfisP13entity_widget, 0x0011DF10");
__asm__(".equ create_anim__10anim_makerRC7stringxRC17entity_track_treeP6entityUsfisP13entity_widget, 0x0011DE18");
__asm__(".equ reset_root_position__16entity_anim_tree, 0x00118470");

entity_anim_tree* entity::play_anim( int slot,
                                     const stringx& _name,
                                     const entity_track_tree& track,
                                     time_value_t start_time,
                                     unsigned short anim_flags,
                                     short loop )
{
//  assert(slot==ANIM_PRIMARY);

  START_PROF_TIMER( proftimer_play_anim1 );
	make_animateable(true);
  //if ( anim_trees == NULL )
  //{
  //  // this is the first time a hierarchical animation has been requested for
  //  // this entity, so we must construct the hierarchical animation list
  //  anim_trees = NEW entity_anim_tree*[MAX_ANIM_SLOTS];
  //  memset( anim_trees, 0, sizeof(entity_anim_tree*)*MAX_ANIM_SLOTS );
  //}

  entity_anim_tree* prev = anim_trees[slot];
  if ( prev )
  {
  	START_PROF_TIMER( proftimer_play_anim1old );
    if ( !prev->is_attached()
      || prev->get_name() != _name
      || prev->is_finished() )
    {
      if ( prev->is_attached() )
      {
        if ( owning_widget )
        {
          owning_widget->kill_anim( prev );
        }
        else
        {
          g_world_ptr->kill_anim( prev );
        }
      }
      // create NEW anim with cached anim tree in this slot
      g_anim_maker->create_anim( anim_trees[slot], _name, track, anim_flags, start_time, slot, loop, owning_widget );
    }
    else
    {
      // apply any flags that are appropriate
      prev->set_flag( ANIM_LOOPING, (anim_flags&ANIM_LOOPING)!=0 );
      prev->set_flag( ANIM_AUTOKILL, (anim_flags&ANIM_AUTOKILL)!=0 );
      if ( (prev->get_flags()&ANIM_REVERSE) != (anim_flags&ANIM_REVERSE) )
      {
        // change reverse play status
        prev->set_flag( ANIM_REVERSE, (anim_flags&ANIM_REVERSE)!=0 );
        // reset keys and root start position values
        prev->set_time( prev->get_time() );
        prev->reset_root_position();
      }
    }
  	STOP_PROF_TIMER( proftimer_play_anim1old );
  }
  else
  {
  	START_PROF_TIMER( proftimer_play_anim1new );
    // construct a NEW anim tree for this slot
    anim_trees[slot] = g_anim_maker->create_anim( _name, track, this, anim_flags, start_time, slot, loop, owning_widget );
  	STOP_PROF_TIMER( proftimer_play_anim1new );
  }

  STOP_PROF_TIMER( proftimer_play_anim1 );
  return anim_trees[slot];
}


void entity::make_animateable( bool onOff )
{
	if ( onOff && anim_trees==NULL )
	{
    // this is the first time a hierarchical animation has been requested for
    // this entity, so we must construct the hierarchical animation list
//    anim_trees = NEW entity_anim_tree*[MAX_ANIM_SLOTS];
    memset( anim_trees, 0, sizeof(entity_anim_tree*)*MAX_ANIM_SLOTS );
	}
  /*
	else
	if ( !onOff && anim_trees!=NULL )
	{
		delete [] anim_trees;
	}
  */
}

entity_anim_tree* entity::play_anim( int slot,
                                     const stringx& _name,
                                     const entity_track_tree& tracka,
                                     const entity_track_tree& trackb,
                                     rational_t blenda,
                                     rational_t blendb,
                                     time_value_t start_time,
                                     unsigned short anim_flags,
                                     short loop )
{
  assert(slot==ANIM_PRIMARY);
  START_PROF_TIMER( proftimer_play_anim2 );
	make_animateable(true);
  //if ( anim_trees == NULL )
  //{
  //  // this is the first time a hierarchical animation has been requested for
  //  // this entity, so we must construct the hierarchical animation list
  //  anim_trees = NEW entity_anim_tree*[MAX_ANIM_SLOTS];
  //  memset( anim_trees, 0, sizeof(entity_anim_tree*)*MAX_ANIM_SLOTS );
  //}

  entity_anim_tree* prev = anim_trees[slot];
  if ( prev )
  {
    if ( !prev->is_attached()
      || prev->get_name() != _name
      || prev->is_finished() )
    {
      if ( prev->is_attached() )
      {
        if ( owning_widget )
        {
          owning_widget->kill_anim( prev );
        }
        else
        {
          g_world_ptr->kill_anim( prev );
        }
      }
      // create NEW anim with cached anim tree in this slot
      g_anim_maker->create_anim( anim_trees[slot], _name, tracka, trackb, blenda, blendb, anim_flags, start_time, slot, loop, owning_widget );
    }
    else
    {
      // apply any flags that are appropriate
      prev->set_flag( ANIM_LOOPING, (anim_flags&ANIM_LOOPING)!=0 );
      prev->set_flag( ANIM_AUTOKILL, (anim_flags&ANIM_AUTOKILL)!=0 );
      if ( (prev->get_flags()&ANIM_REVERSE) != (anim_flags&ANIM_REVERSE) )
      {
        // change reverse play status
        prev->set_flag( ANIM_REVERSE, (anim_flags&ANIM_REVERSE)!=0 );
        // reset keys and root start position values
        prev->set_time( prev->get_time() );
        prev->reset_root_position();
      }
    }
  }
  else
  {
    // construct a NEW anim tree for this slot
    anim_trees[slot] = g_anim_maker->create_anim( _name, tracka, trackb, blenda, blendb, this, anim_flags, start_time, slot, loop, owning_widget );
  }

  STOP_PROF_TIMER( proftimer_play_anim2 );
  return anim_trees[slot];
}
